import java.io.PrintWriter;
import java.util.Arrays;

public class Main {
    static class Edge implements Comparable<Edge> {
        int u, v, weight;

        Edge(int u, int v, int weight) {
            this.u = u;
            this.v = v;
            this.weight = weight;
        }

        @Override
        public int compareTo(Edge o) {
            return Integer.compare(o.weight, this.weight); // Ordem decrescente
        }
    }

    static class DSU {
        int[] parent;

        DSU(int n) {
            parent = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
            }
        }

        int find(int i) {
            if (parent[i] == i)
                return i;
            return parent[i] = find(parent[i]);
        }

        boolean union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                parent[rootI] = rootJ;
                return true;
            }
            return false;
        }
    }

    // Estrutura para a árvore (grafo da Maximum Spanning Tree)
    static int[] head, to, nextEdge, edgeWeight;
    static int edgeCount = 0;

    static void addTreeEdge(int u, int v, int w) {
        to[edgeCount] = v;
        edgeWeight[edgeCount] = w;
        nextEdge[edgeCount] = head[u];
        head[u] = edgeCount++;

        to[edgeCount] = u;
        edgeWeight[edgeCount] = w;
        nextEdge[edgeCount] = head[v];
        head[v] = edgeCount++;
    }

    static final int LOGN = 18;
    static int[][] up;
    static int[][] minWeight;
    static int[] depth;

    static void dfs(int u, int p, int w, int d) {
        depth[u] = d;
        up[u][0] = p;
        minWeight[u][0] = w;

        for (int i = 1; i < LOGN; i++) {
            up[u][i] = up[up[u][i - 1]][i - 1];
            minWeight[u][i] = Math.min(minWeight[u][i - 1], minWeight[up[u][i - 1]][i - 1]);
        }

        for (int e = head[u]; e != -1; e = nextEdge[e]) {
            int v = to[e];
            if (v != p) {
                dfs(v, u, edgeWeight[e], d + 1);
            }
        }
    }

    static int query(int u, int v) {
        int ans = Integer.MAX_VALUE;

        if (depth[u] < depth[v]) {
            int temp = u;
            u = v;
            v = temp;
        }

        // Subir 'u' até o mesmo nível de 'v'
        for (int i = LOGN - 1; i >= 0; i--) {
            if (depth[u] - (1 << i) >= depth[v]) {
                ans = Math.min(ans, minWeight[u][i]);
                u = up[u][i];
            }
        }

        if (u == v) {
            return ans;
