        for (int i = LOGN - 1; i >= 0; i--) {
            if (up[u][i] != up[v][i]) {
                ans = Math.min(ans, minWeight[u][i]);
                ans = Math.min(ans, minWeight[v][i]);
                u = up[u][i];
                v = up[v][i];
            }
        }

        ans = Math.min(ans, minWeight[u][0]);
        ans = Math.min(ans, minWeight[v][0]);
        return ans;
    }

