const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const B = nextInt();

    const u_edge = new Int32Array(B);
    const v_edge = new Int32Array(B);
    const w_edge = new Int32Array(B);

    for (let i = 0; i < B; i++) {
        u_edge[i] = nextInt();
        v_edge[i] = nextInt();
        w_edge[i] = nextInt();
    }

    const edgeIndices = new Int32Array(B);
    for (let i = 0; i < B; i++) {
        edgeIndices[i] = i;
    }
    edgeIndices.sort((a, b) => w_edge[b] - w_edge[a]);

    // DSU para Kruskal
    const parentDSU = new Int32Array(N + 1);
    for (let i = 1; i <= N; i++) parentDSU[i] = i;

    function find(i) {
        let root = i;
        while (root !== parentDSU[root]) {
            root = parentDSU[root];
        }
        let curr = i;
        while (curr !== root) {
            let nxt = parentDSU[curr];
            parentDSU[curr] = root;
            curr = nxt;
        }
        return root;
    }

    // Grafo da Árvore Geradora Máxima (MST)
    const head = new Int32Array(N + 1).fill(-1);
    const to = new Int32Array(2 * (N - 1));
    const weight = new Int32Array(2 * (N - 1));
    const nextEdge = new Int32Array(2 * (N - 1));
    let edgeCount = 0;

    function addTreeEdge(u, v, w) {
        to[edgeCount] = v;
        weight[edgeCount] = w;
        nextEdge[edgeCount] = head[u];
        head[u] = edgeCount++;

        to[edgeCount] = u;
        weight[edgeCount] = w;
        nextEdge[edgeCount] = head[v];
        head[v] = edgeCount++;
    }

    let edgesAdded = 0;
    for (let i = 0; i < B; i++) {
        const idx = edgeIndices[i];
        const u = u_edge[idx];
        const v = v_edge[idx];
        const rootU = find(u);
        const rootV = find(v);
        if (rootU !== rootV) {
            parentDSU[rootU] = rootV;
            addTreeEdge(u, v, w_edge[idx]);
            edgesAdded++;
            if (edgesAdded === N - 1) break;
        }
    }

    // Binary Lifting LCA
    const LOG = 18;
    const up = [];
    const minEdge = [];
    for (let k = 0; k < LOG; k++) {
        up.push(new Int32Array(N + 1));
        minEdge.push(new Int32Array(N + 1).fill(1e9));
    }
    const depth = new Int32Array(N + 1);

    // BFS para preencher nível 0 do binary lifting sem recursão
    const queue = new Int32Array(N + 1);
    let qHead = 0;
    let qTail = 0;

    const visited = new Uint8Array(N + 1);
    queue[qTail++] = 1;
    visited[1] = 1;
    up[0][1] = 1;
    minEdge[0][1] = 1e9;
    depth[1] = 0;

    while (qHead < qTail) {
        const u = queue[qHead++];
        let e = head[u];
        while (e !== -1) {
            const v = to[e];
            const w = weight[e];
            if (!visited[v]) {
                visited[v] = 1;
                depth[v] = depth[u] + 1;
                up[0][v] = u;
                minEdge[0][v] = w;
                queue[qTail++] = v;
            }
            e = nextEdge[e];
        }
    }

    // Preenche as potências de 2
    for (let k = 1; k < LOG; k++) {
        const upK = up[k];
        const upPrev = up[k - 1];
        const minK = minEdge[k];
        const minPrev = minEdge[k - 1];
        for (let i = 1; i <= N; i++) {
            const ancestor = upPrev[i];
            upK[i] = upPrev[ancestor];
            minK[i] = minPrev[i] < minPrev[ancestor] ? minPrev[i] : minPrev[ancestor];
        }
    }

    function query(u, v) {
        let ans = 1e9;

        if (depth[u] < depth[v]) {
            let tmp = u; u = v; v = tmp;
        }

        let diff = depth[u] - depth[v];
        for (let k = LOG - 1; k >= 0; k--) {
            if ((diff & (1 << k)) !== 0) {
                if (minEdge[k][u] < ans) ans = minEdge[k][u];
                u = up[k][u];
            }
        }

        if (u === v) return ans;

        for (let k = LOG - 1; k >= 0; k--) {
            if (up[k][u] !== up[k][v]) {
                if (minEdge[k][u] < ans) ans = minEdge[k][u];
                if (minEdge[k][v] < ans) ans = minEdge[k][v];
                u = up[k][u];
                v = up[k][v];
            }
        }

        if (minEdge[0][u] < ans) ans = minEdge[0][u];
        if (minEdge[0][v] < ans) ans = minEdge[0][v];

        return ans;
    }

    const C = nextInt();
    let out = '';
    for (let i = 0; i < C; i++) {
        const X = nextInt();
        const Y = nextInt();
        out += query(X, Y) + '\n';
        if (out.length >= 65536) {
            process.stdout.write(out);
            out = '';
        }
    }

    if (out.length > 0) {
        process.stdout.write(out);
    }
}

